# 读取输入，按题意求解
import sys

data = list(map(int, sys.stdin.buffer.read().split()))
it = iter(data)
t = next(it)
out = []
for _ in range(t):
    n = next(it)
    cnt_odd = 0       # 记录奇数个数
    has_even = False  # 是否出现偶数
    for _ in range(n):
        x = next(it)
        if x % 2 == 0:
            has_even = True
        else:
            cnt_odd += 1
    # 若存在偶数，最少操作为奇数个数；否则已全奇，答案为0
    out.append(str(cnt_odd if has_even else 0))

print("\n".join(out))
```

### Java

```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int T = sc.nextInt(); // 读取测试组数
        StringBuilder sb = new StringBuilder();
        while (T-- > 0) {
            int n = sc.nextInt(); 
            int cntOdd = 0;      // 统计奇数个数
            boolean hasEven = false; // 是否存在偶数
            for (int i = 0; i < n; i++) {
                int x = sc.nextInt();
                if ((x & 1) == 0) hasEven = true; // 偶数
                else cntOdd++; // 奇数
            }
            // 若存在偶数，答案为奇数个数；否则已全奇，答案为0
            sb.append(hasEven ? cntOdd : 0).append('\n');
        }
        System.out.print(sb.toString());
    }
}
